const body = $json.body ?? {};
const headers = $json.headers ?? {};
const action = String(body.action ?? '').trim();
const code = String(body.code ?? '').trim();

const API_KEY = 'JISR-DEMO-1448';
const receivedKey = String(headers['x-jisr-key'] ?? headers['X-JISR-Key'] ?? '');

if (receivedKey !== API_KEY) {
  return [{ json: { success: false, message: 'مفتاح API غير صحيح' } }];
}

const store = $getWorkflowStaticData('global');

const pad = (n) => String(n).padStart(2, '0');

function now() {
  const d = new Date(Date.now() + (3 * 60 * 60 * 1000));
  return {
    date: `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`,
    iso: `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}`,
    stamp: `${d.getUTCFullYear()}${pad(d.getUTCMonth() + 1)}${pad(d.getUTCDate())}${pad(d.getUTCHours())}${pad(d.getUTCMinutes())}${pad(d.getUTCSeconds())}`,
  };
}

function makeId(prefix) {
  return `${prefix}-${now().stamp}-${Math.random().toString(36).slice(2, 5).toUpperCase()}`;
}

