function dataIsValid() {
  return (
    Array.isArray(store.parents) &&
    Array.isArray(store.students) &&
    Array.isArray(store.admins) &&
    Array.isArray(store.requests) &&
    Array.isArray(store.announcements) &&
    Array.isArray(store.acks) &&
    Array.isArray(store.events)
  );
}

if (!dataIsValid()) {
  seed();
}

function parentByCode(value) {
  return store.parents.find((x) => x.code === value);
}

function studentByCode(value) {
  return store.students.find((x) => x.code === value);
}

function adminByCode(value) {
  return store.admins.find((x) => x.code === value);
}

function parentOf(student) {
  return store.parents.find((p) => p.id === student.parentId);
}

function safeRequest(r) {
  const st = store.students.find((x) => x.id === r.studentId);
  const p = store.parents.find((x) => x.id === r.parentId);

  return {
    ...r,
    studentName: st?.name ?? '',
    grade: st?.grade ?? '',
    className: st?.className ?? '',
    parentName: p?.name ?? '',
  };
}

function schedule() {
  const rows = [
    ['الرياضيات', 'أ. محمد', '7:00 - 7:45'],
    ['العلوم', 'أ. خالد', '7:45 - 8:30'],
    ['لغتي', 'أ. أحمد', '8:30 - 9:15'],
    ['اللغة الإنجليزية', 'أ. سالم', '9:35 - 10:20'],
    ['الدراسات الإسلامية', 'أ. عبدالله', '10:20 - 11:05'],
    ['المهارات الرقمية', 'أ. فهد', '11:05 - 11:50'],
    ['التربية البدنية', 'أ. ناصر', '11:50 - 12:35'],
  ];

  return rows.map(([subject, teacher, time]) => ({ subject, teacher, time }));
}

function notificationsFor(role, userId, student = null) {
  return store.announcements
    .filter((ann) => {
      if (role === 'parent') {
        return ann.audienceRole === 'parent' || ann.audienceRole === 'both';
      }

      if (role === 'student') {
        const roleOk = ann.audienceRole === 'student' || ann.audienceRole === 'both';
        const audienceOk = ann.audience === 'الجميع' || ann.audience === student?.grade;
        return roleOk && audienceOk;
      }

      return false;
    })
    .map((ann) => {
      const acknowledged = store.acks.some(
        (ack) =>
          ack.annId === ann.id &&
          ack.userType === role &&
          ack.userId === userId
      );

      return {
        ...ann,
        acknowledged,
        read: acknowledged,
      };
    })
    .sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));
}

if (action === 'ping') {
  return [{
    json: {
      success: true,
      version: '0.92',
      message: 'JISR V0.92 online',
      serverTime: now().iso,
    },
  }];
}

if (action === 'login') {
  const requestedRole = String(body.role ?? '');

  let user = null;
  if (requestedRole === 'parent') user = parentByCode(code);
  if (requestedRole === 'student') user = studentByCode(code);
  if (requestedRole === 'admin') user = adminByCode(code);

  if (!user) {
    return [{ json: { success: false, message: 'رمز الدخول غير صحيح' } }];
  }

  return [{
    json: {
      success: true,
      user: {
        id: user.id ?? 'ADMIN',
        name: user.name,
        role: requestedRole,
        roleLabel:
          requestedRole === 'parent'
            ? 'ولي أمر'
            : requestedRole === 'student'
              ? 'طالب'
              : 'إدارة المدرسة',
      },
    },
  }];
}

if (action === 'dashboard') {
  const parent = parentByCode(code);

  if (parent) {
    const children = store.students.filter((st) => parent.children.includes(st.id));
    const requests = store.requests
      .filter((r) => r.parentId === parent.id)
      .map(safeRequest)
      .sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));

    const notifications = notificationsFor('parent', parent.id);

    const timeline = store.events
      .filter(
        (event) =>
          event.userId === 'ALL' ||
          event.userId === parent.id ||
          children.some((child) => child.id === event.studentId)
      )
      .sort((a, b) => String(b.at).localeCompare(String(a.at)));

    return [{
      json: {
        success: true,
        role: 'parent',
        version: '0.92',
        generatedAt: now().iso,
        parent,
        children,
        requests,
        notifications,
        unreadCount: notifications.filter(
          (x) => x.requiresAck && !x.acknowledged
        ).length,
        timeline,
        summary: {
          pending: requests.filter((r) => r.status === 'قيد المراجعة').length,
          approved: requests.filter((r) => r.status === 'مقبول').length,
          appointments: requests.filter((r) => r.type === 'موعد').length,
        },
      },
    }];
  }

  const student = studentByCode(code);

  if (student) {
    const notifications = notificationsFor('student', student.id, student);

    return [{
      json: {
        success: true,
        role: 'student',
        version: '0.92',
        generatedAt: now().iso,
        student: {
          ...student,
          schedule: schedule(),
        },
        notifications,
        unreadCount: notifications.filter(
          (x) => x.requiresAck && !x.acknowledged
        ).length,
        pulse: [
          {
            title: 'الحضور',
            text: student.presentToday
              ? 'تم تسجيل حضورك اليوم ✓'
              : 'لم يسجل حضورك بعد',
          },
          {
            title: 'الإشادات',
            text: `لديك ${student.praise} إشادات إيجابية`,
          },
          {
            title: 'التنبيهات',
            text: student.alerts
              ? `لديك ${student.alerts} تنبيه`
              : 'لا توجد ملاحظات اليوم',
          },
        ],
      },
    }];
  }

  const admin = adminByCode(code);

  if (admin) {
    const requests = store.requests
      .map(safeRequest)
      .sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));

    const announcements = store.announcements
      .map((ann) => {
        let targetCount = 0;

        if (ann.audienceRole === 'parent') {
          targetCount = store.parents.length;
        } else if (ann.audienceRole === 'student') {
          targetCount = store.students.filter(
            (st) => ann.audience === 'الجميع' || st.grade === ann.audience
          ).length;
        } else {
          const studentTargets = store.students.filter(
            (st) => ann.audience === 'الجميع' || st.grade === ann.audience
          ).length;
          targetCount = store.parents.length + studentTargets;
        }

        const ackCount = store.acks.filter((x) => x.annId === ann.id).length;

        return {
          ...ann,
          targetCount,
          ackCount,
        };
      })
      .sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));

    const notificationTargets = announcements.reduce(
      (sum, ann) => sum + ann.targetCount,
      0
    );

    const notificationAcks = announcements.reduce(
      (sum, ann) => sum + ann.ackCount,
      0
    );

    const students = store.students.map((st) => ({
      ...st,
      parentName: parentOf(st)?.name ?? '',
      parentPhone: parentOf(st)?.phone ?? '',
      familyRequests: store.requests.filter((r) => r.studentId === st.id).length,
    }));

    return [{
      json: {
        success: true,
        role: 'admin',
        version: '0.92',
        generatedAt: now().iso,
        requests,
        announcements,
        students,
        parents: store.parents,
        timeline: [...store.events].sort(
          (a, b) => String(b.at).localeCompare(String(a.at))
        ),
        unreadCount: requests.filter((r) => r.status === 'قيد المراجعة').length,
        summary: {
          totalRequests: requests.length,
          pending: requests.filter((r) => r.status === 'قيد المراجعة').length,
          approved: requests.filter((r) => r.status === 'مقبول').length,
          rejected: requests.filter((r) => r.status === 'مرفوض').length,
          announcements: announcements.length,
          notificationTargets,
          notificationAcks,
          readRate: notificationTargets
            ? Math.round((notificationAcks / notificationTargets) * 100)
            : 0,
          leaveRequests: requests.filter((r) => r.type === 'استئذان').length,
          excuses: requests.filter((r) => r.type === 'عذر غياب').length,
          appointments: requests.filter((r) => r.type === 'موعد').length,
          inquiries: requests.filter((r) => r.type === 'استفسار').length,
        },
      },
    }];
  }

  return [{
    json: {
      success: false,
      message: 'الحساب غير معروف أو لم يصل رمز الدخول إلى Dashboard',
    },
  }];
}

if (action === 'createRequest') {
  const parent = parentByCode(code);

  if (!parent) {
    return [{ json: { success: false, message: 'هذه العملية لولي الأمر فقط' } }];
  }

  const student = store.students.find(
    (st) => st.id === String(body.studentId ?? '') && parent.children.includes(st.id)
  );

  if (!student) {
    return [{ json: { success: false, message: 'الطالب غير مرتبط بولي الأمر' } }];
  }

  const type = String(body.type ?? '').trim();
  const details = String(body.details ?? '').trim();

  if (!type || !details) {
    return [{ json: { success: false, message: 'نوع الطلب والتفاصيل مطلوبان' } }];
  }

  const request = {
    id: makeId('REQ'),
    parentId: parent.id,
    studentId: student.id,
    type,
    details,
    requestedDate: String(body.requestedDate ?? ''),
    requestedTime: String(body.requestedTime ?? ''),
    target: String(body.target ?? ''),
    createdAt: now().iso,
    status: 'قيد المراجعة',
    schoolNote: '',
    decisionAt: '',
    decisionBy: '',
    messages: [],
  };

  store.requests.unshift(request);

  store.events.unshift({
    id: makeId('EV'),
    type: 'طلب',
    userId: parent.id,
    studentId: student.id,
    title: `طلب ${type} جديد`,
    description: `${student.name} · ${request.id}`,
    at: now().iso,
  });

  return [{
    json: {
      success: true,
      message: 'تم إرسال الطلب للمدرسة',
      requestId: request.id,
    },
  }];
}

if (action === 'decision') {
  const admin = adminByCode(code);

  if (!admin) {
    return [{ json: { success: false, message: 'غير مصرح بهذه العملية' } }];
  }

  const request = store.requests.find((r) => r.id === String(body.id ?? ''));

  if (!request) {
    return [{ json: { success: false, message: 'الطلب غير موجود' } }];
  }

  const status = String(body.status ?? '');

  if (!['مقبول', 'مرفوض'].includes(status)) {
    return [{ json: { success: false, message: 'قرار غير صالح' } }];
  }

  request.status = status;
  request.schoolNote = String(body.schoolNote ?? '');
  request.decisionAt = now().iso;
  request.decisionBy = String(body.staffName ?? admin.name);

  request.messages.push({
    fromRole: 'school',
    from: request.decisionBy,
    text:
      request.schoolNote ||
      (status === 'مقبول' ? 'تم اعتماد الطلب.' : 'تم رفض الطلب.'),
    at: now().iso,
  });

  const student = store.students.find((st) => st.id === request.studentId);

  store.events.unshift({
    id: makeId('EV'),
    type: 'طلب',
    userId: request.parentId,
    studentId: request.studentId,
    title:
      status === 'مقبول'
        ? `تم اعتماد ${request.type}`
        : `تم رفض ${request.type}`,
    description: `${student?.name ?? ''} · ${request.id}`,
    at: now().iso,
  });

  return [{ json: { success: true, message: 'تم حفظ القرار' } }];
}

if (action === 'sendMessage') {
  const request = store.requests.find(
    (r) => r.id === String(body.requestId ?? '')
  );

  const text = String(body.text ?? '').trim();

  if (!request || !text) {
    return [{ json: { success: false, message: 'الطلب والرسالة مطلوبان' } }];
  }

  request.messages.push({
    fromRole: String(body.fromRole ?? 'parent'),
    from: String(body.from ?? 'المستخدم'),
    text,
    at: now().iso,
  });

  return [{ json: { success: true, message: 'تم إرسال الرسالة' } }];
}

if (action === 'createAnnouncement') {
  const admin = adminByCode(code);

  if (!admin) {
    return [{ json: { success: false, message: 'غير مصرح بهذه العملية' } }];
  }

  const title = String(body.title ?? '').trim();
  const announcementBody = String(body.body ?? '').trim();

  if (!title || !announcementBody) {
    return [{ json: { success: false, message: 'العنوان والنص مطلوبان' } }];
  }

  const announcement = {
    id: makeId('ANN'),
    title,
    body: announcementBody,
    audienceRole: String(body.audienceRole ?? 'parent'),
    audience: String(body.audience ?? 'الجميع'),
    requiresAck: Boolean(body.requiresAck),
    createdAt: now().iso,
    createdBy: String(body.staffName ?? admin.name),
  };

  store.announcements.unshift(announcement);

  store.events.unshift({
    id: makeId('EV'),
    type: 'إشعار',
    userId: 'ALL',
    studentId: '',
    title,
    description: 'إشعار جديد من المدرسة',
    at: now().iso,
  });

  return [{ json: { success: true, message: 'تم إرسال الإشعار' } }];
}

if (action === 'ackNotification') {
  const parent = parentByCode(code);
  const student = studentByCode(code);

  const userId = parent?.id ?? student?.id;
  const userType = parent ? 'parent' : student ? 'student' : '';

  if (!userId) {
    return [{ json: { success: false, message: 'غير مصرح' } }];
  }

  const annId = String(body.id ?? '');

  if (!store.announcements.some((ann) => ann.id === annId)) {
    return [{ json: { success: false, message: 'الإشعار غير موجود' } }];
  }

  const exists = store.acks.some(
    (ack) =>
      ack.annId === annId &&
      ack.userType === userType &&
      ack.userId === userId
  );

  if (!exists) {
    store.acks.push({
      annId,
      userType,
      userId,
      at: now().iso,
    });
  }

  return [{ json: { success: true, message: 'تم تأكيد الاطلاع' } }];
}

if (action === 'resetDemo') {
  seed();
  return [{ json: { success: true, message: 'تمت إعادة بيانات التجربة' } }];
}

return [{ json: { success: false, message: 'الإجراء غير مدعوم' } }];
